do $$
begin
  -- add (state from the seed rules: QoH 0 -> closed; Product "1" stays unknown)
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='LOT-NEW') = 'seed' and (select source from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='LOT-NEW') = 'seed:2026-11-08-delivery', 'new lot added with the new source';
  assert (select product_external_id from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='LOT-NEW') = 'P-NEW', 'new lot product';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Product' and external_id='P-NEW') = 'seed', 'new product added';
  -- refresh (untouched seed rows only)
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='LOT-ZERO') = 'closed', 'zeroed lot refreshed to closed';
  assert (select filed_name from public.ccrs_filed_entities where env='prod' and file_type='Product' and external_id='P-REN') = 'Renamed 1g', 'renamed product refreshed';
  assert (select seed_payload->>'Quantity on Hand' from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='O''Brien.LOT') = '1', 'quoted id refreshed';
  -- settle
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='MIG-1') = 'seed' and (select product_external_id from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='MIG-1') = 'P-1', 'migration lot now on file';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='UNC-1') = 'confirmed', 'uncertain proven by the copy -> confirmed';
  -- never written
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='UNC-LATE') = 'uncertain', 'uncertain uploaded on the copy day stays uncertain';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='OURS-1') = 'filed' and (select source from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='OURS-1') like 'file:%', 'our filing untouched';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='DEL-1') = 'deleted', 'deleted stays deleted';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='LOT-GONE') = 'seed', 'missing seed row untouched';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='UNC-ABS') = 'uncertain', 'absent uncertain untouched';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='MIG-2') = 'unknown', 'unfiled migration lot still held';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Product' and external_id='1') = 'unknown', 'junk product id stays unknown';
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='LOT-SAME') = 'seed' and (select source from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='LOT-SAME') = 'seed:2026-09-18-delivery', 'unchanged row keeps its source';
  -- the 0248 invariant: the import lot not on the record is held
  assert (select state from public.ccrs_filed_entities where env='prod' and file_type='Inventory' and external_id='MIG-3') = 'unknown', 'migration lot linked as unknown';
  -- totals, counted without the linker's rows (the database may hold other import lots)
  assert (select count(*) from public.ccrs_filed_entities where env='prod' and source <> 'link:unfiled-migration-lot') = 18, 'row total';
  assert (select count(*) from public.ccrs_filed_entities where env='prod' and source = 'seed:2026-11-08-delivery') = 7, 'every write carries the new source';
  -- provenance: four closed seed pseudo-files for the new delivery
  assert (select count(*) from public.ccrs_files where env='prod' and purpose='seed' and state='closed' and file_name like 'seed:2026-11-08-delivery:%') = 4, 'provenance recorded';
end $$;

